import {
  type Component,
  type ComponentProps,
  mergeProps,
  Show,
  splitProps,
} from "solid-js";

import { cn } from "~/lib/utils.ts";

type DeltaBarProps = ComponentProps<"div"> & {
  value: number;
  isIncreasePositive?: boolean;
};

const DeltaBar: Component<DeltaBarProps> = (rawProps) => {
  const props = mergeProps(
    {
      isIncreasePositive: true,
    },
    rawProps,
  );
  const [local, others] = splitProps(props, [
    "value",
    "isIncreasePositive",
    "class",
  ]);

  const barColor = () =>
    (local.value > 0 && local.isIncreasePositive) ||
      (local.value < 0 && !local.isIncreasePositive)
      ? "bg-success-foreground"
      : "bg-error-foreground";

  return (
    <div
      class={cn(
        "h-2 rounded-full bg-secondary relative flex w-full items-center",
        local.class,
      )}
      {...others}
    >
      <div class="flex h-full w-1/2 justify-end">
        <Show when={local.value < 0}>
          <div
            class={cn("rounded-l-full", barColor())}
            style={{ width: `${Math.abs(local.value)}%` }}
          />
        </Show>
      </div>
      <div
        class={cn(
          "h-4 w-1 rounded-full ring-2 ring-background z-10",
          barColor(),
        )}
      />
      <div class="flex h-full w-1/2 justify-start">
        <Show when={local.value > 0}>
          <div
            class={cn("rounded-r-full", barColor())}
            style={{ width: `${Math.abs(local.value)}%` }}
          />
        </Show>
      </div>
    </div>
  );
};

export { DeltaBar };
export type { DeltaBarProps };
